O quadro de transferênciasThe transfer board

Foi nessas cidades e bairros que os missionários trabalharam. A cada transferência, as duplas mudavam e as zonas se reorganizavam. Escolha um mês para ver o quadro e toque num nome para ver quando o missionário chegou ao campo missionário. Viu algum erro? Escreva para info@ochamado.org.These are the cities and neighborhoods where the missionaries served. At every transfer, companionships changed and zones were reorganized. Pick a month to see the board, and tap a name to see when that missionary arrived in the mission field. Spot a mistake? Email info@ochamado.org.


quadro = FileAttachment("data/quadro.json").json()
snaps = quadro.snapshots
pessoas = new Map(quadro.missionarios.map(p =&gt; [p.id, p]))
viewof idioma = {
  const el = htl.html`&lt;span hidden&gt;&lt;/span&gt;`;
  el.value = document.documentElement.dataset.lang === "en" ? "en" : "pt";
  window.addEventListener("ochamado:idioma", () =&gt; {
    el.value = document.documentElement.dataset.lang === "en" ? "en" : "pt";
    el.dispatchEvent(new Event("input"));
  });
  return el;
}
T = (pt, en) =&gt; idioma === "en" ? en : pt
MES = idioma === "en"
  ? ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
  : ["jan", "fev", "mar", "abr", "mai", "jun", "jul", "ago", "set", "out", "nov", "dez"]
MES_NOME = idioma === "en"
  ? ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"]
  : ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"]
fmtYM = k =&gt; { if (!k) return "—"; const [y, m] = k.split("-"); return idioma === "en" ? `${MES[+m - 1]} ${y}` : `${MES[+m - 1]}/${y}`; }
fmtMesAno = s =&gt; idioma === "en" ? `${MES_NOME[s.mes - 1]} ${s.ano}` : `${MES_NOME[s.mes - 1].toLowerCase()} de ${s.ano}`
nacionalidade = n =&gt; idioma === "en" ? ({ "brasileiro": "Brazilian", "norte americano": "North American" }[n] ?? n) : n
nomeCompleto = l =&gt; l.replace(/^E\s+/, "Élder ").replace(/^S\s+/, "Síster ")
norm = s =&gt; String(s ?? "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/-/g, " ").replace(/\s+/g, " ").trim()
aparicoes = {
  const m = new Map();
  for (const s of snaps) for (const z of s.zonas) for (const a of z.areas) for (const p of a.dupla) {
    const k = p.id ?? "?" + p.n;
    if (!m.has(k)) m.set(k, []);
    m.get(k).push({ key: s.key, zona: z.nome, especial: z.especial, areaNome: a.nome, area: a.rotulo ?? z.nome, companheiros: a.dupla.filter(x =&gt; x !== p) });
  }
  return m;
}
function estado(v) { const el = htl.html`&lt;span hidden&gt;&lt;/span&gt;`; el.value = v; return el; }
function definir(el, v) { el.value = v; el.dispatchEvent(new Event("input", { bubbles: true })); }
viewof quadroKey = estado("1997-10")
DIVISAO = "1998-07"
snapIdx = snaps.findIndex(s =&gt; s.key === quadroKey)
snapAtual = snaps[snapIdx]







































































































































{
  const first = snaps[0], last = snaps[snaps.length - 1];
  const max = Math.max(...snaps.map(s =&gt; s.stats.zonas));
  const W = 640, H = 56, gap = 3, bw = W / snaps.length;
  const tile = (num, lbl, base) =&gt; htl.html`&lt;div class="stat-tile"&gt;&lt;div class="num"&gt;${num}&lt;/div&gt;&lt;div class="lbl"&gt;${lbl}&lt;/div&gt;&lt;/div&gt;`;
  return htl.html`&lt;div&gt;
    &lt;p class="growth-headline"&gt;&lt;strong&gt;${first.stats.zonas}&lt;/strong&gt; ${T("zonas em", "zones in")} ${fmtYM(first.key)} → &lt;strong&gt;${last.stats.zonas}&lt;/strong&gt; ${T("zonas em", "zones in")} ${fmtYM(last.key)}&lt;/p&gt;
    &lt;div class="stat-tiles"&gt;
      ${tile(snapAtual.stats.zonas, T("Zonas", "Zones"))}
      ${tile(snapAtual.stats.areas, T("Áreas", "Areas"))}
      ${tile(snapAtual.stats.missionarios, T("Missionários", "Missionaries"))}
    &lt;/div&gt;
    ${htl.svg`&lt;svg class="growth-bars" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label=${T("Zonas por mês", "Zones per month")}&gt;
      ${snaps.map((s, i) =&gt; {
        const h = Math.max(4, (s.stats.zonas / max) * H);
        return htl.svg`&lt;rect class=${s.key === quadroKey ? "active" : ""} x=${i * bw + gap / 2} y=${H - h} width=${bw - gap} height=${h} rx="2"
          onclick=${() =&gt; definir(viewof quadroKey, s.key)}&gt;&lt;title&gt;${fmtYM(s.key)}: ${s.stats.zonas} ${T("zonas", "zones")}&lt;/title&gt;&lt;/rect&gt;`;
      })}
      ${(() =&gt; {
        const i = snaps.findIndex(s =&gt; s.key === DIVISAO);
        return i &lt; 0 ? "" : htl.svg`&lt;line class="marco-divisao" x1=${i * bw} x2=${i * bw} y1="0" y2=${H}&gt;&lt;title&gt;${T("Julho de 1998: divisão da missão", "July 1998: the mission is divided")}&lt;/title&gt;&lt;/line&gt;`;
      })()}
    &lt;/svg&gt;`}
    &lt;p class="growth-nota"&gt;&lt;span class="marco"&gt;&lt;/span&gt; ${T("Julho de 1998: a missão foi dividida para formar a Missão Brasil Santa Maria.", "July 1998: the mission was divided to create the Brazil Santa Maria Mission.")}&lt;/p&gt;
  &lt;/div&gt;`;
}







{
  const anos = [...new Set(snaps.map(s =&gt; s.ano))];
  const doAno = snaps.filter(s =&gt; s.ano === snapAtual.ano);
  const go = k =&gt; definir(viewof quadroKey, k);
  const pill = (label, active, onclick) =&gt; htl.html`&lt;button class=${active ? "pill active" : "pill"} onclick=${onclick}&gt;${label}&lt;/button&gt;`;
  return htl.html`&lt;div class="filter-panel"&gt;
    &lt;div class="pill-group"&gt;${anos.map(a =&gt; pill(a, a === snapAtual.ano, () =&gt; go(snaps.find(s =&gt; s.ano === a).key)))}&lt;/div&gt;
    &lt;div class="pill-group"&gt;${doAno.map(s =&gt; pill(MES[s.mes - 1], s.key === quadroKey, () =&gt; go(s.key)))}&lt;/div&gt;
  &lt;/div&gt;
  ${quadroKey === DIVISAO
    ? htl.html`&lt;p class="aviso-divisao"&gt;&lt;i class="bi bi-signpost-split"&gt;&lt;/i&gt;&lt;span&gt;${idioma === "en"
      ? htl.html`This month the mission was divided to create the &lt;strong&gt;Brazil Santa Maria Mission&lt;/strong&gt;. The Ijuí and Santo Ângelo zones went to the new mission.`
      : htl.html`Neste mês a missão foi dividida para formar a &lt;strong&gt;Missão Brasil Santa Maria&lt;/strong&gt;. As zonas de Ijuí e Santo Ângelo passaram para a nova missão.`}&lt;/span&gt;&lt;/p&gt;`
    : ""}`;
}







chaveArea = (nome, zona) =&gt; {
  const k = norm(nome);
  return /^rio branco/.test(k) ? k + (["Moinhos de Vento", "Porto Alegre"].includes(zona) ? "|poa" : "|serra") : k;
}

historicoArea = {
  const m = new Map();
  snaps.forEach((s, i) =&gt; {
    for (const z of s.zonas) {
      if (z.especial) continue;
      for (const a of z.areas) {
        if (!a.nome) continue;
        const k = chaveArea(a.nome, z.nome);
        if (!m.has(k)) m.set(k, { nome: a.nome, zonas: [], duplas: new Map(), ini: i, fim: i });
        const h = m.get(k);
        h.fim = i;
        if (!h.zonas.includes(z.nome)) h.zonas.push(z.nome);
        const dk = a.dupla.map(p =&gt; p.id ?? "?" + p.n).sort().join("+");
        if (!h.duplas.has(dk)) h.duplas.set(dk, { dupla: a.dupla, idx: [] });
        const d = h.duplas.get(dk);
        if (d.idx.at(-1) !== i) d.idx.push(i);
      }
    }
  });
  return m;
}

dlgArea = {
  const d = htl.html`&lt;dialog class="dialogo-area" aria-labelledby="dlg-area-titulo"&gt;&lt;/dialog&gt;`;
  d.addEventListener("click", e =&gt; { if (e.target === d) d.close(); });
  return d;
}

chavePessoa = p =&gt; p.id ?? "?" + p.n

// The area and missionary dialogs link to each other, so their functions share one cell
// (separate OJS cells may not reference each other in a cycle).
dialogos = {
  // The same dialog shows an area or a missionary; links inside it swap its content.
  function mostrarDialogo(conteudo) {
    dlgArea.replaceChildren(conteudo);
    if (!dlgArea.open) dlgArea.showModal();
    dlgArea.scrollTop = 0;
  }

  function topoDialogo(titulo, meta) {
    return htl.html`&lt;div class="dlg-topo"&gt;
      &lt;div&gt;&lt;h3 id="dlg-area-titulo"&gt;${titulo}&lt;/h3&gt;${meta}&lt;/div&gt;
      &lt;button class="dlg-fechar" aria-label=${T("Fechar", "Close")} onclick=${() =&gt; dlgArea.close()}&gt;&lt;i class="bi bi-x-lg"&gt;&lt;/i&gt;&lt;/button&gt;
    &lt;/div&gt;`;
  }


  // A missionary's name (or a ditto mark for a repeat) that opens their dialog.
  function botaoPessoa(p, rep = false) {
    const nome = nomeCompleto(p.n);
    // A repeat is a plain mark (not clickable); the full name shows on hover.
    if (rep) return htl.html`&lt;span class="ditto" title=${nome}&gt;${dittoConteudo(nome)}&lt;/span&gt;`;
    return htl.html`&lt;button class=${"link-caixa" + (p.id ? "" : " sem-registro")} onclick=${() =&gt; abrirPessoa(p)}&gt;${nome}&lt;/button&gt;`;
  }

  // One table row per companionship run; each missionary has a column, and someone who also
  // appears in the row above keeps that column and is shown as a ditto mark.
  function linhaHistoricoArea(periodoTxt, cols, atual) {
    const tds = cols.map(c =&gt; c ? htl.html`&lt;td&gt;${botaoPessoa(c.p, c.rep)}&lt;/td&gt;` : htl.html`&lt;td&gt;&lt;/td&gt;`);
    return htl.html`&lt;tr class=${atual ? "atual" : ""}&gt;&lt;td class="periodo"&gt;${periodoTxt}&lt;/td&gt;${tds}&lt;/tr&gt;`;
  }

  // A missionary's boards: zone, area and companions, with ditto marks for repeats.
  function tabelaPessoa(ap) {
    return htl.html`&lt;div class="table-scroll"&gt;&lt;table class="historico-table"&gt;
      &lt;thead&gt;&lt;tr&gt;&lt;th&gt;${T("Quadro", "Board")}&lt;/th&gt;&lt;th&gt;${T("Zona", "Zone")}&lt;/th&gt;&lt;th&gt;${T("Área", "Area")}&lt;/th&gt;&lt;th&gt;${T("Companheiros", "Companions")}&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
      &lt;tbody&gt;${ap.map((a, i) =&gt; {
        const ant = ap[i - 1];
        const repZona = ant && ant.zona === a.zona;
        const repArea = ant && ant.area === a.area;
        const compAnt = new Set(ant ? ant.companheiros.map(chavePessoa) : []);
        const ditto = (txt, rep) =&gt; rep ? htl.html`&lt;span class="ditto" title=${txt}&gt;${dittoConteudo(txt)}&lt;/span&gt;` : txt;
        return htl.html`&lt;tr class=${a.key === snapAtual.key ? "atual" : ""}&gt;&lt;td class="periodo"&gt;${fmtYM(a.key)}&lt;/td&gt;&lt;td&gt;${ditto(a.zona, repZona)}&lt;/td&gt;
          &lt;td&gt;${a.areaNome && !a.especial && !repArea
            ? htl.html`&lt;button class="link-caixa" title=${T("Ver todas as duplas desta área", "See every companionship in this area")}
                onclick=${() =&gt; abrirArea({ nome: a.areaNome }, { nome: a.zona })}&gt;${a.area}&lt;/button&gt;`
            : ditto(a.area, repArea)}&lt;/td&gt;
          &lt;td class="companheiros"&gt;${a.companheiros.map(c =&gt; botaoPessoa(c, compAnt.has(chavePessoa(c))))}&lt;/td&gt;&lt;/tr&gt;`;
      })}&lt;/tbody&gt;
    &lt;/table&gt;&lt;/div&gt;`;
  }

  function abrirPessoa(p) {
    const x = p.id ? pessoas.get(p.id) : null;
    const ap = aparicoes.get(chavePessoa(p)) ?? [];
    const nQuadros = `${T("em", "on")} ${ap.length} ${ap.length === 1 ? T("quadro", "board") : T("quadros", "boards")}`;
    const provavel = p.c === "inferido" || p.c === "tolerancia";
    const meta = x
      ? htl.html`&lt;div class="meta"&gt;${x.nacionalidade ? `${nacionalidade(x.nacionalidade)} · ` : ""}&lt;strong&gt;${T("Chegada", "Arrived")}&lt;/strong&gt; ${fmtYM(x.chegada)} · &lt;strong&gt;${T("Saída", "Left")}&lt;/strong&gt; ${fmtYM(x.saida)} · ${nQuadros}${provavel ? htl.html` · &lt;span class="provavel"&gt;${T("identificação provável", "probable match")}&lt;/span&gt;` : ""}&lt;/div&gt;`
      : htl.html`&lt;div class="meta"&gt;${T("Sem registro de chegada/saída", "No arrival/departure record")} · ${nQuadros}&lt;/div&gt;`;
    mostrarDialogo(htl.html`${topoDialogo(x ? `${x.titulo} ${x.plaqueta}` : nomeCompleto(p.n), meta)}
      &lt;div class="dlg-corpo"&gt;
        ${ap.length ? tabelaPessoa(ap) : htl.html`&lt;p class="busca-hint"&gt;${T("Não aparece nos quadros de transferências.", "Not on any transfer board.")}&lt;/p&gt;`}
        ${x ? "" : htl.html`&lt;p class="dlg-nota"&gt;${T("Ainda não conseguimos ligar este nome a ninguém da lista de missionários. Se você sabe quem é, escreva para info@ochamado.org.",
          "We couldn't match this name to anyone on the missionary list yet. If you know who it is, email info@ochamado.org.")}&lt;/p&gt;`}
        &lt;p class="dlg-nota"&gt;${T("A chegada é o mês em que o missionário chegou ao campo missionário. ↓ = igual à linha de cima. A linha destacada é o mês escolhido no quadro.",
          "Arrival is the month the missionary arrived in the mission field. ↓ = same as the row above. The highlighted row is the month selected on the board.")}&lt;/p&gt;
      &lt;/div&gt;`);
  }

  function abrirArea(a, z) {
    const h = historicoArea.get(chaveArea(a.nome, z.nome));
    if (!h) return;
    const linhas = [];
    for (const { dupla, idx } of h.duplas.values()) {
      let ini = idx[0], ant = idx[0];
      for (const i of [...idx.slice(1), null]) {
        if (i === ant + 1) { ant = i; continue; }
        linhas.push({ ini, fim: ant, dupla });
        ini = ant = i;
      }
    }
    linhas.sort((x, y) =&gt; x.ini - y.ini || x.fim - y.fim);
    const nPessoas = new Set(linhas.flatMap(r =&gt; r.dupla.map(p =&gt; p.id ?? "?" + p.n))).size;
    const periodo = r =&gt; r.ini === r.fim ? fmtYM(snaps[r.ini].key) : `${fmtYM(snaps[r.ini].key)} – ${fmtYM(snaps[r.fim].key)}`;
    const zonas = h.zonas.join(", ");
    const chave = p =&gt; p.id ?? "?" + p.n;
    const nCol = Math.max(2, ...linhas.map(r =&gt; r.dupla.length));
    let colsAnt = [];
    const linhasCols = linhas.map(r =&gt; {
      const cols = Array(nCol).fill(null), resto = [];
      for (const p of r.dupla) {
        const j = colsAnt.findIndex(q =&gt; q && chave(q) === chave(p));
        if (j &gt;= 0 && !cols[j]) cols[j] = { p, rep: true }; else resto.push(p);
      }
      for (const p of resto) cols[cols.findIndex(c =&gt; !c)] = { p, rep: false };
      colsAnt = cols.map(c =&gt; c && c.p);
      return { r, cols };
    });
    const meta = htl.html`&lt;div class="meta"&gt;${T(h.zonas.length &gt; 1 ? "Zonas" : "Zona", h.zonas.length &gt; 1 ? "Zones" : "Zone")}: ${zonas} · ${nPessoas} ${T("missionários", "missionaries")}&lt;/div&gt;`;
    mostrarDialogo(htl.html`${topoDialogo(h.nome, meta)}
      &lt;div class="dlg-corpo"&gt;
        &lt;table class="historico-table historico-area"&gt;
          &lt;thead&gt;&lt;tr&gt;&lt;th&gt;${T("Quando", "When")}&lt;/th&gt;&lt;th colspan=${nCol}&gt;${T("Dupla", "Companionship")}&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
          &lt;tbody&gt;${linhasCols.map(({ r, cols }) =&gt; linhaHistoricoArea(periodo(r), cols, snapIdx &gt;= r.ini && snapIdx &lt;= r.fim))}&lt;/tbody&gt;
        &lt;/table&gt;
        &lt;p class="dlg-nota"&gt;${T("↓ = mesmo missionário da linha de cima. Meses seguidos com a mesma dupla aparecem numa linha só. A linha destacada é o mês escolhido no quadro.",
          "↓ = same missionary as the row above. Consecutive months with the same companionship are shown as one row. The highlighted row is the month selected on the board.")}&lt;/p&gt;
      &lt;/div&gt;`);
  }

  return { abrirArea, abrirPessoa };
}

abrirArea = dialogos.abrirArea

abrirPessoa = dialogos.abrirPessoa

// Repeat mark: a down arrow, set in a little from the left edge of the text above.
function dittoConteudo(txt) {
  return htl.html`&lt;span class="ditto-marca" aria-hidden="true"&gt;&lt;i class="bi bi-arrow-down"&gt;&lt;/i&gt;&lt;/span&gt;`;
}

function linhaArea(a, z, cont) {
  const chips = a.dupla.map(p =&gt; htl.html`&lt;button class=${p.id ? "chip" : "chip sem-registro"} onclick=${() =&gt; abrirPessoa(p)}&gt;${nomeCompleto(p.n)}&lt;/button&gt;`);
  return htl.html`&lt;div class=${cont ? "area-row cont" : "area-row"}&gt;
    ${a.nome ? htl.html`&lt;div class="area-name"&gt;${z.especial ? a.nome : htl.html`&lt;button class="area-link link-caixa" title=${T("Ver todas as duplas desta área", "See every companionship in this area")} onclick=${() =&gt; abrirArea(a, z)}&gt;${a.nome}&lt;i class="bi bi-clock-history"&gt;&lt;/i&gt;&lt;/button&gt;`}${a.total &gt; 1 ? htl.html`&lt;span class="dupla-tag"&gt;#${a.n}&lt;/span&gt;` : ""}&lt;/div&gt;` : ""}
    &lt;div class="nomes"&gt;${chips}&lt;/div&gt;
  &lt;/div&gt;`;
}

































































// Zone toggles for the areas map: one button per zone of the month, plus all / none.
{
  const zonas = snapAtual.zonas.filter(z =&gt; !z.especial).map(z =&gt; z.nome);
  const ocultas = new Set(zonasOcultas);
  const alternar = nome =&gt; {
    const s = new Set(zonasOcultas);
    s.has(nome) ? s.delete(nome) : s.add(nome);
    definir(viewof zonasOcultas, [...s]);
  };
  return htl.html`&lt;div class="filtro-zonas"&gt;
    &lt;span class="filtro-rotulo"&gt;${T("Zonas", "Zones")}&lt;/span&gt;
    &lt;button class="filtro-tudo" onclick=${() =&gt; definir(viewof zonasOcultas, [])}&gt;${T("Todas", "All")}&lt;/button&gt;
    &lt;button class="filtro-tudo" onclick=${() =&gt; definir(viewof zonasOcultas, TODAS_ZONAS)}&gt;${T("Nenhuma", "None")}&lt;/button&gt;
    ${zonas.map(n =&gt; htl.html`&lt;button class=${ocultas.has(n) ? "filtro-zona off" : "filtro-zona"} aria-pressed=${!ocultas.has(n)} onclick=${() =&gt; alternar(n)}&gt;
      &lt;span class="cor" style=${`background:${corZona(n)}`}&gt;&lt;/span&gt;${n}&lt;/button&gt;`)}
  &lt;/div&gt;`;
}







ZONA_POS = ({
  "Porto Alegre": [-30.035, -51.225], "Moinhos de Vento": [-30.012, -51.190], "Guaíba": [-30.114, -51.325],
  "Canoas": [-29.917, -51.183], "Canoas-Esteio": [-29.852, -51.179], "Gravataí": [-29.944, -50.992],
  "São Leopoldo": [-29.760, -51.147], "Novo Hamburgo": [-29.678, -51.131], "Taquara": [-29.650, -50.781],
  "Montenegro": [-29.689, -51.461], "Caxias do Sul": [-29.168, -51.179], "Bento Gonçalves": [-29.171, -51.519],
  "Vacaria": [-28.512, -50.934], "Passo Fundo": [-28.262, -52.408], "Vergueiro": [-28.230, -52.440],
  "Erechim": [-27.634, -52.274], "Osório": [-29.887, -50.270], "Capão da Canoa": [-29.745, -50.010],
  "Ijuí": [-28.388, -53.914], "Santo Ângelo": [-28.299, -54.263]
})

// A fixed color per zone (same in every month). Neighboring zones get clearly different hues.
ZONA_COR = ({
  "Porto Alegre": "#1f6fb4", "Moinhos de Vento": "#8e44ad", "Guaíba": "#17a2b8", "Canoas": "#d62728",
  "Canoas-Esteio": "#e377c2", "Gravataí": "#ff7f0e", "São Leopoldo": "#2ca02c", "Novo Hamburgo": "#8c564b",
  "Taquara": "#a9a619", "Montenegro": "#006d77", "Caxias do Sul": "#b5179e", "Bento Gonçalves": "#e9a23b",
  "Vacaria": "#264653", "Passo Fundo": "#3a86ff", "Vergueiro": "#6a3fd0", "Erechim": "#2a9d8f",
  "Osório": "#ef476f", "Capão da Canoa": "#06a77d", "Ijuí": "#e76f51", "Santo Ângelo": "#9c6644",
  "Assistentes": "#1b5e46", "Staff": "#5c6370", "Élderes Viajantes": "#b8862a"
})
// Assistants, Staff and Traveling Elders worked from the mission office, Av. Princesa Isabel 342, Porto Alegre.
ESCRITORIO = [-30.0505, -51.2115]
TODAS_ZONAS = [...new Set(snaps.flatMap(s =&gt; s.zonas.filter(z =&gt; !z.especial).map(z =&gt; z.nome)))]
// The office groups (Assistants, Staff, Traveling Elders) show only while every zone is on;
// once specific zones are picked, only those zones show.
